/**
 * FRONTEND EXERCISE, Part A: see docs/learn/07-frontend.md, section "Exercise".
 * Run with: npm run test:exercises   (they fail until you do the exercise; do not edit this file)
 */
import { act, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { fakeApi, json, problem } from '../test/fakeApi';
import { placedOrder, putMugInCart } from '../test/shopping';

describe('Part A: checkout after a 429', () => {
  beforeEach(() => vi.useFakeTimers({ shouldAdvanceTime: true }));
  afterEach(() => vi.useRealTimers());

  it('waits out Retry-After with a countdown on the button, then lets the customer try again', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
    const server = fakeApi().on('POST /orders',
      problem(429, 'Too many requests', {}, { 'Retry-After': '30' }), json(placedOrder, 201));
    await putMugInCart(server, { user });

    await user.click(screen.getByRole('button', { name: 'Place order' }));

    expect(await screen.findByRole('button', { name: 'Try again in 30 s' })).toBeDisabled();
    await act(() => vi.advanceTimersByTimeAsync(10_000));
    expect(screen.getByRole('button', { name: 'Try again in 20 s' })).toBeDisabled();
    await act(() => vi.advanceTimersByTimeAsync(20_000));

    const again = screen.getByRole('button', { name: 'Place order' });
    expect(again).toBeEnabled();
    await user.click(again);
    expect(await screen.findByText(/Order #99 was placed/)).toBeInTheDocument();
    // The refused attempt never ran on the server: retrying it is the same purchase, same key.
    const [first, second] = server.callsTo('POST /orders');
    expect(second.headers.get('Idempotency-Key')).toBe(first.headers.get('Idempotency-Key'));
  });

  it('waits 5 seconds when the server did not say how long', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
    const server = fakeApi().on('POST /orders', problem(429, 'Too many requests'));
    await putMugInCart(server, { user });

    await user.click(screen.getByRole('button', { name: 'Place order' }));

    expect(await screen.findByRole('button', { name: 'Try again in 5 s' })).toBeDisabled();
  });

  it('other errors do not start a countdown', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
    const server = fakeApi().on('POST /orders', problem(409, 'Insufficient stock for product 7', { productId: 7 }));
    await putMugInCart(server, { user });

    await user.click(screen.getByRole('button', { name: 'Place order' }));

    expect(await screen.findByRole('alert')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Place order' })).toBeEnabled();
  });
});
